const contacts = $input.all();
const today = new Date();
today.setHours(0,0,0,0);

const INTERVALS = {
  'cold': 14,
  'warm': 7,
  'potential client': 5,
  'high potential': 3
};

const FOLLOW_UP_ELIGIBLE = ['cold', 'warm', 'potential client', 'high potential'];

const FOLLOW_UP_MESSAGES = {
  'cold': 'Hello {name}, just checking in from Kamilight Global Logistics. We help businesses move cargo efficiently across Africa. Would you be open to a quick conversation about your freight needs?',
  'warm': 'Hi {name}, following up from Kamilight. We have capacity this month and competitive rates. Are you still looking for a freight partner?',
  'potential client': 'Hello {name}, this is Kamilight Global Logistics. Are you still exploring freight solutions? We have a new offer we\'d love to share with you.',
  'high potential': 'Hi {name}, our team has prepared a proposal for your business. Can we share it this week?'
};

const due = [];

for (const item of contacts) {
  const c = item.json;
  const tag = c.Tag?.toLowerCase()?.trim();
  const optOut = c['WhatsApp Opt-Out'];
  const responseStatus = c['Response Status']?.toLowerCase();

  // Only follow up with eligible tags
  if (!FOLLOW_UP_ELIGIBLE.includes(tag)) continue;

  // Skip opt-outs
  if (optOut === 'TRUE' || optOut === true) continue;

  // Skip if already responded positively
  if (responseStatus === 'interested' || responseStatus === 'not_interested') continue;

  // Check if follow-up is due
  const lastContacted = c['Last Contacted'];
  const interval = INTERVALS[tag] || 7;

  let isDue = false;
  if (!lastContacted || lastContacted.trim() === '') {
    // Never contacted — definitely due
    isDue = true;
  } else {
    const lastDate = new Date(lastContacted);
    const daysSince = Math.floor((today - lastDate) / (1000 * 60 * 60 * 24));
    isDue = daysSince >= interval;
  }

  if (!isDue) continue;

  // Format phone
  let phone = (c.Phone || '').replace(/\D/g, '');
  if (phone.startsWith('0') && phone.length === 11) phone = '234' + phone.substring(1);
  if (phone.length < 7 || phone.length > 15) continue;

  // Personalize message
  const name = c.Name?.split(' ')[0] || 'there';
  const template = FOLLOW_UP_MESSAGES[tag] || FOLLOW_UP_MESSAGES['cold'];
  const message = template.replace('{name}', name);

  due.push({
    json: {
      name: c.Name,
      first_name: name,
      phone,
      tag,
      message,
      row_phone: c.Phone // Original for sheet update
    }
  });
}

if (due.length === 0) {
  // Return empty signal
  return [{ json: { no_followups_due: true, checked_at: today.toISOString() } }];
}

return due;
